import { Prisma } from '@prisma/client'
import { prisma } from '@/lib/prisma'

export const MOODS = ['happy', 'neutral', 'sad', 'angry', 'anxious'] as const
export type Mood = (typeof MOODS)[number]

export interface DiaryData {
  mood: Mood
  content: string
  date: string
}

export interface DiaryUpdateData {
  mood?: Mood
  content?: string
}

function parseDate(date: string): Date {
  const [year, month, day] = date.split('-').map(Number)
  return new Date(Date.UTC(year, month - 1, day))
}

function monthRange(month: string) {
  const [year, monthIndex] = month.split('-').map(Number)
  const start = new Date(Date.UTC(year, monthIndex - 1, 1))
  const end = new Date(Date.UTC(year, monthIndex, 1))
  return { start, end }
}

export class DiaryConflictError extends Error {
  constructor() {
    super('동일한 날짜의 일기가 이미 존재합니다.')
    this.name = 'DiaryConflictError'
  }
}

export async function listDiaries(userId: string, month: string) {
  const { start, end } = monthRange(month)
  return prisma.diary.findMany({
    where: {
      userId,
      date: {
        gte: start,
        lt: end,
      },
    },
    orderBy: { date: 'asc' },
  })
}

export async function getDiaryByDate(userId: string, date: string) {
  const parsed = parseDate(date)
  return prisma.diary.findUnique({
    where: {
      userId_date: {
        userId,
        date: parsed,
      },
    },
  })
}

export async function createDiary(userId: string, data: DiaryData) {
  const { mood, content, date } = data
  const parsedDate = parseDate(date)

  try {
    return await prisma.diary.create({
      data: {
        userId,
        mood,
        content,
        date: parsedDate,
      },
    })
  } catch (e) {
    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === 'P2002') {
      throw new DiaryConflictError()
    }
    throw e
  }
}

export async function updateDiary(
  userId: string,
  id: string,
  data: DiaryUpdateData,
) {
  const existing = await prisma.diary.findUnique({ where: { id } })
  if (!existing || existing.userId !== userId) {
    return null
  }

  return prisma.diary.update({
    where: { id },
    data,
  })
}

export async function deleteDiary(userId: string, id: string) {
  const existing = await prisma.diary.findUnique({ where: { id } })
  if (!existing || existing.userId !== userId) {
    return null
  }

  await prisma.diary.delete({ where: { id } })
  return existing
}

import { Request, Response, NextFunction, Router } from 'express'
import { z } from 'zod'
import { requireAuth } from '@/middleware/auth'
import {
  MOODS,
  DiaryConflictError,
  listDiaries,
  getDiaryByDate,
  createDiary,
  updateDiary,
  deleteDiary,
} from '@/services/diary'
import type { Diary } from '@prisma/client'

const router = Router()

const dateStringSchema = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/, '날짜는 YYYY-MM-DD 형식이어야 합니다.')

const monthSchema = z
  .string()
  .regex(/^\d{4}-\d{2}$/, '월은 YYYY-MM 형식이어야 합니다.')

const moodSchema = z.enum(MOODS, {
  message: '감정은 happy, neutral, sad, angry, anxious 중 하나여야 합니다.',
})

const createSchema = z.object({
  date: dateStringSchema,
  mood: moodSchema,
  content: z.string().min(1, '내용을 입력하세요.'),
})

const updateSchema = z
  .object({
    mood: moodSchema.optional(),
    content: z.string().min(1, '내용을 입력하세요.').optional(),
  })
  .refine((data) => data.mood !== undefined || data.content !== undefined, {
    message: '수정할 감정이나 내용을 입력하세요.',
  })

type AsyncHandler = (req: Request, res: Response, next: NextFunction) => Promise<void>

function asyncRoute(handler: AsyncHandler) {
  return (req: Request, res: Response, next: NextFunction) => {
    handler(req, res, next).catch(next)
  }
}

function toApi(diary: Diary) {
  return {
    id: diary.id,
    userId: diary.userId,
    mood: diary.mood,
    content: diary.content,
    date: diary.date.toISOString().split('T')[0],
    createdAt: diary.createdAt.toISOString(),
    updatedAt: diary.updatedAt.toISOString(),
  }
}

router.get(
  '/',
  requireAuth,
  asyncRoute(async (req, res) => {
    const parsed = monthSchema.safeParse(req.query.month)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const diaries = await listDiaries(req.user!.id, parsed.data)
    res.json({ diaries: diaries.map(toApi) })
  }),
)

router.get(
  '/:date',
  requireAuth,
  asyncRoute(async (req, res) => {
    const parsed = dateStringSchema.safeParse(req.params.date)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const diary = await getDiaryByDate(req.user!.id, parsed.data)
    res.json({ diary: diary ? toApi(diary) : null })
  }),
)

router.post(
  '/',
  requireAuth,
  asyncRoute(async (req, res, next) => {
    const parsed = createSchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    try {
      const diary = await createDiary(req.user!.id, parsed.data)
      res.status(201).json({ diary: toApi(diary) })
    } catch (e) {
      if (e instanceof DiaryConflictError) {
        res.status(409).json({ error: e.message })
        return
      }
      next(e)
    }
  }),
)

router.put(
  '/:id',
  requireAuth,
  asyncRoute(async (req, res) => {
    const id = req.params.id
    const parsed = updateSchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const diary = await updateDiary(req.user!.id, id, parsed.data)
    if (!diary) {
      res.status(404).json({ error: '일기를 찾을 수 없습니다.' })
      return
    }

    res.json({ diary: toApi(diary) })
  }),
)

router.delete(
  '/:id',
  requireAuth,
  asyncRoute(async (req, res) => {
    const id = req.params.id
    const diary = await deleteDiary(req.user!.id, id)
    if (!diary) {
      res.status(404).json({ error: '일기를 찾을 수 없습니다.' })
      return
    }

    res.json({ ok: true })
  }),
)

export default router

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import api from '@/lib/axios'
import type { Diary, DiaryCreateInput, DiaryUpdateInput } from '@/types/schemas'

export function useDiaries(month: string) {
  return useQuery({
    queryKey: ['diaries', month],
    queryFn: async () => {
      const { data } = await api.get<{ diaries: Diary[] }>('/diaries', {
        params: { month },
      })
      return data.diaries
    },
    enabled: !!month,
    staleTime: 5 * 60 * 1000,
  })
}

export function useDiary(date: string) {
  return useQuery({
    queryKey: ['diaries', date],
    queryFn: async () => {
      const { data } = await api.get<{ diary: Diary | null }>(`/diaries/${date}`)
      return data.diary
    },
    enabled: !!date,
    staleTime: 5 * 60 * 1000,
  })
}

export function useCreateDiary() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (input: DiaryCreateInput) => {
      const { data } = await api.post<{ diary: Diary }>('/diaries', input)
      return data.diary
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['diaries'] })
    },
  })
}

export function useUpdateDiary() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ id, input }: { id: string; input: DiaryUpdateInput }) => {
      const { data } = await api.put<{ diary: Diary }>(`/diaries/${id}`, input)
      return data.diary
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['diaries'] })
    },
  })
}

export function useDeleteDiary() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (id: string) => {
      await api.delete(`/diaries/${id}`)
      return id
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['diaries'] })
    },
  })
}

import { useEffect, useState } from 'react'
import { isAxiosError } from 'axios'
import { cn } from '@/lib/utils'
import { useDiaries, useDiary, useCreateDiary, useUpdateDiary, useDeleteDiary } from '@/api/diary'
import { diaryCreateSchema, diaryUpdateSchema, type Mood } from '@/types/schemas'

const MOOD_OPTIONS: { value: Mood; label: string; color: string }[] = [
  { value: 'happy', label: '행복', color: 'bg-green-100 text-green-800 ring-green-300' },
  { value: 'neutral', label: '보통', color: 'bg-gray-100 text-gray-800 ring-gray-300' },
  { value: 'sad', label: '슬픔', color: 'bg-blue-100 text-blue-800 ring-blue-300' },
  { value: 'angry', label: '분노', color: 'bg-red-100 text-red-800 ring-red-300' },
  { value: 'anxious', label: '불안', color: 'bg-purple-100 text-purple-800 ring-purple-300' },
]

function toDateString(date: Date): string {
  return date.toLocaleDateString('sv-SE')
}

function toMonthString(date: Date): string {
  return toDateString(date).slice(0, 7)
}

export default function Diary() {
  const [selectedDate, setSelectedDate] = useState<string>(() => toDateString(new Date()))
  const [mood, setMood] = useState<Mood>('neutral')
  const [content, setContent] = useState('')
  const [loadedDiaryId, setLoadedDiaryId] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  const month = selectedDate.slice(0, 7)
  const { data: diary, isLoading: isDiaryLoading } = useDiary(selectedDate)
  const { data: diaries = [], isLoading: isListLoading } = useDiaries(month)
  const { mutate: createDiary, isPending: isCreating } = useCreateDiary()
  const { mutate: updateDiary, isPending: isUpdating } = useUpdateDiary()
  const { mutate: deleteDiary, isPending: isDeleting } = useDeleteDiary()

  const isBusy = isCreating || isUpdating || isDeleting

  useEffect(() => {
    if (diary) {
      if (diary.id !== loadedDiaryId) {
        setMood(diary.mood as Mood)
        setContent(diary.content)
        setLoadedDiaryId(diary.id)
        setError(null)
      }
    } else if (loadedDiaryId !== null) {
      setMood('neutral')
      setContent('')
      setLoadedDiaryId(null)
      setError(null)
    }
  }, [diary, loadedDiaryId])

  const validate = () => {
    if (diary) {
      const parsed = diaryUpdateSchema.safeParse({ mood, content })
      if (!parsed.success) {
        setError(parsed.error.errors[0].message)
        return false
      }
      return true
    }

    const parsed = diaryCreateSchema.safeParse({ date: selectedDate, mood, content })
    if (!parsed.success) {
      setError(parsed.error.errors[0].message)
      return false
    }
    return true
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)

    if (!validate()) {
      return
    }

    if (diary) {
      const payload = { mood, content }
      updateDiary(
        { id: diary.id, input: payload },
        {
          onError: (err) => {
            if (isAxiosError(err) && err.response?.data?.error) {
              setError(err.response.data.error)
            } else {
              setError('일기 수정 중 오류가 발생했습니다.')
            }
          },
        },
      )
      return
    }

    createDiary(
      { date: selectedDate, mood, content },
      {
        onError: (err) => {
          if (isAxiosError(err) && err.response?.status === 409) {
            setError(err.response.data?.error ?? '동일한 날짜의 일기가 이미 존재합니다.')
          } else if (isAxiosError(err) && err.response?.data?.error) {
            setError(err.response.data.error)
          } else {
            setError('일기 저장 중 오류가 발생했습니다.')
          }
        },
      },
    )
  }

  const handleDelete = () => {
    if (!diary) return
    setError(null)
    deleteDiary(diary.id, {
      onError: (err) => {
        if (isAxiosError(err) && err.response?.data?.error) {
          setError(err.response.data.error)
        } else {
          setError('일기 삭제 중 오류가 발생했습니다.')
        }
      },
    })
  }

  const changeMonth = (offset: number) => {
    const [year, monthIndex] = month.split('-').map(Number)
    const next = new Date(Date.UTC(year, monthIndex - 1 + offset, 1))
    setSelectedDate(toDateString(next))
  }

  const getMood = (value: Mood) => MOOD_OPTIONS.find((m) => m.value === value) ?? MOOD_OPTIONS[1]

  return (
    <div className="min-h-screen bg-background p-4 md:p-8">
      <div className="mx-auto max-w-3xl space-y-6">
        <h1 className="text-2xl font-bold text-foreground">일기</h1>

        <form
          onSubmit={handleSubmit}
          noValidate
